const reopenSession = `-- name: ReopenSession :exec
UPDATE address_search_sessions
SET ended_at = NULL
WHERE id = $1::uuid AND ended_at = $2::timestamptz
`

type ReopenSessionParams struct {
	ID      uuid.UUID
	EndedAt time.Time
}

// ReopenSession takes back the end of a resolve whose provider call
// failed, so the caller may try again; a later end stays.
func (q *Queries) ReopenSession(ctx context.Context, arg ReopenSessionParams) error {
	_, err := q.db.Exec(ctx, reopenSession, arg.ID, arg.EndedAt)
	return err
}

const replaceAddress = `-- name: ReplaceAddress :exec
UPDATE active_addresses
SET city_id = $1,
    district_id = $2,
    neighborhood = $3,
    thoroughfare = $4,
    building_number = $5,
    building_name = $6,
    site_name = $7,
    block = $8,
    floor = $9,
    unit_number = $10,
    postal_code = $11,
    additional_directions = $12,
    provider_place_id = $13,
    latitude = $14,
    longitude = $15,
    components_source = $16,
    coordinate_source = $17,
    updated_at = $18
WHERE id = $19 AND user_id = $20
`

type ReplaceAddressParams struct {
	CityID               uuid.UUID
	DistrictID           uuid.UUID
	Neighborhood         *string
	Thoroughfare         *string
	BuildingNumber       *string
	BuildingName         *string
	SiteName             *string
	Block                *string
	Floor                *string
	UnitNumber           *string
	PostalCode           *string
	AdditionalDirections *string
	ProviderPlaceID      *string
	Latitude             *float64
	Longitude            *float64
	ComponentsSource     string
	CoordinateSource     *string
	UpdatedAt            time.Time
	ID                   uuid.UUID
	UserID               uuid.UUID
}

// ReplaceAddress rewrites one of the user's addresses; the caller holds
// its row (LockAddress).
func (q *Queries) ReplaceAddress(ctx context.Context, arg ReplaceAddressParams) error {
	_, err := q.db.Exec(ctx, replaceAddress,
		arg.CityID,
		arg.DistrictID,
		arg.Neighborhood,
		arg.Thoroughfare,
		arg.BuildingNumber,
		arg.BuildingName,
		arg.SiteName,
		arg.Block,
		arg.Floor,
		arg.UnitNumber,
		arg.PostalCode,
		arg.AdditionalDirections,
		arg.ProviderPlaceID,
		arg.Latitude,
		arg.Longitude,
		arg.ComponentsSource,
		arg.CoordinateSource,
		arg.UpdatedAt,
		arg.ID,
		arg.UserID,
	)
	return err
}

const setPrimaryAddress = `-- name: SetPrimaryAddress :exec
UPDATE active_users
SET address_id = $1::uuid
WHERE id = $2::uuid
`

type SetPrimaryAddressParams struct {
	AddressID uuid.NullUUID
	ID        uuid.UUID
}

// SetPrimaryAddress points the profile at one of the user's addresses or
// clears the link; the caller holds the user's row (LockOwner) and, for an
// address, the address's row (OwnAddress).
func (q *Queries) SetPrimaryAddress(ctx context.Context, arg SetPrimaryAddressParams) error {
	_, err := q.db.Exec(ctx, setPrimaryAddress, arg.AddressID, arg.ID)
	return err
}

const storeAreaBounds = `-- name: StoreAreaBounds :exec
UPDATE address_area_bounds
SET south = $1::double precision,
    west = $2::double precision,
    north = $3::double precision,
    east = $4::double precision,
    fetched_at = $5::timestamptz,
    failures = 0,
    retry_at = NULL
WHERE city_id = $6::uuid
`

type StoreAreaBoundsParams struct {
	South     float64
	West      float64
	North     float64
	East      float64
	FetchedAt time.Time
	CityID    uuid.UUID
}

// StoreAreaBounds keeps a looked-up rectangle and clears the backoff.
func (q *Queries) StoreAreaBounds(ctx context.Context, arg StoreAreaBoundsParams) error {
	_, err := q.db.Exec(ctx, storeAreaBounds,
		arg.South,
		arg.West,
		arg.North,
		arg.East,
		arg.FetchedAt,
		arg.CityID,
	)
	return err
}
